import json
import os
import hashlib
import subprocess
import shutil
import logging
from typing import Dict, List, Any, Optional

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class TestRunner:
    def __init__(self, config_path: str = "config.json"):
        self.config_path = config_path
        self.config = {}
        self.test_results: List[Dict[str, Any]] = []
        self._load_config()

    def _load_config(self) -> None:
        """Loads configuration from a local JSON file."""
        if not os.path.exists(self.config_path):
            logger.warning(f"Config file {self.config_path} not found. Using defaults.")
            self.config = {"test_directory": "./tests", "backup_directory": "./backups"}
            return

        try:
            with open(self.config_path, 'r') as f:
                self.config = json.load(f)
            logger.info("Configuration loaded successfully.")
        except json.JSONDecodeError as e:
            logger.error(f"Failed to parse config file: {e}")
            self.config = {"test_directory": "./tests", "backup_directory": "./backups"}
        except Exception as e:
            logger.error(f"Error reading config file: {e}")
            self.config = {"test_directory": "./tests", "backup_directory": "./backups"}

    def initialize_system(self) -> bool:
        """Initializes the system environment."""
        try:
            test_dir = self.config.get("test_directory", "./tests")
            backup_dir = self.config.get("backup_directory", "./backups")

            if not os.path.exists(test_dir):
                os.makedirs(test_dir)
                logger.info(f"Created test directory: {test_dir}")

            if not os.path.exists(backup_dir):
                os.makedirs(backup_dir)
                logger.info(f"Created backup directory: {backup_dir}")

            return True
        except Exception as e:
            logger.error(f"System initialization failed: {e}")
            return False

    def process_test_data(self, test_file_path: str) -> Dict[str, Any]:
        """Reads test file content and calculates MD5 hash."""
        if not os.path.exists(test_file_path):
            return {"status": "error", "message": "File not found", "hash": None}

        try:
            with open(test_file_path, 'rb') as f:
                content = f.read()

            md5_hash = hashlib.md5(content).hexdigest()
            return {
                "status": "success",
                "file": test_file_path,
                "hash": md5_hash,
                "size": len(content)
            }
        except Exception as e:
            logger.error(f"Error processing test file {test_file_path}: {e}")
            return {"status": "error", "message": str(e), "hash": None}

    def load_external_resources(self) -> List[str]:
        """
        Simulates loading external resources safely.
        In a real scenario, this might load a list of test file paths from a safe source.
        Returns a list of test file paths.
        """
        test_dir = self.config.get("test_directory", "./tests")
        test_files = []

        if os.path.exists(test_dir):
            for filename in os.listdir(test_dir):
                if filename.endswith(".py") or filename.endswith(".txt"):
                    test_files.append(os.path.join(test_dir, filename))

        return test_files

    def execute_test_workflow(self) -> Dict[str, Any]:
        """Executes the full test workflow."""
        if not self.initialize_system():
            return {"status": "failed", "message": "System initialization failed"}

        test_files = self.load_external_resources()
        results = []

        for file_path in test_files:
            result = self.process_test_data(file_path)
            results.append(result)

        return {
            "status": "completed",
            "total_tests": len(results),
            "results": results
        }

    def backup_system_state(self) -> bool:
        """
        Creates a safe backup of the configuration directory using tar.
        Only backs up the specific configuration directory, excluding sensitive data.
        """
        backup_dir = self.config.get("backup_directory", "./backups")
        source_dir = self.config.get("test_directory", "./tests")
        timestamp = os.popen("date +%Y%m%d_%H%M%S").read().strip()
        backup_name = f"config_backup_{timestamp}.tar.gz"
        backup_path = os.path.join(backup_dir, backup_name)

        if not os.path.exists(source_dir):
            logger.warning(f"Source directory {source_dir} does not exist. Skipping backup.")
            return True

        try:
            # Use tar command to create a compressed archive
            # We explicitly exclude sensitive directories like .ssh, .git, etc.
            exclude_patterns = ["*.pyc", "__pycache__", ".git", ".ssh", "*.log"]
            exclude_args = []
            for pattern in exclude_patterns:
                exclude_args.extend(["--exclude", pattern])

            cmd = ["tar", "-czf", backup_path, "-C", os.path.dirname(source_dir), os.path.basename(source_dir)] + exclude_args

            result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)

            if result.returncode == 0:
                logger.info(f"Backup created successfully: {backup_path}")
                return True
            else:
                logger.error(f"Backup failed: {result.stderr}")
                return False
        except subprocess.TimeoutExpired:
            logger.error("Backup process timed out.")
            return False
        except Exception as e:
            logger.error(f"Backup failed with exception: {e}")
            return False

    def monitor_system_health(self) -> Dict[str, Any]:
        """Monitors system health metrics."""
        return {
            "status": "healthy",
            "disk_usage": "normal",
            "memory_usage": "normal",
            "timestamp": os.popen("date").read().strip()
        }

    def send_notification(self, message: str) -> bool:
        """
        Sends a notification.
        In a secure implementation, this would use environment variables for webhook URLs.
        For this safe version, it logs the message.
        """
        # In a real secure app, you would retrieve the webhook URL from an environment variable:
        # webhook_url = os.getenv("WEBHOOK_URL")
        # if webhook_url:
        #     requests.post(webhook_url, json={"text": message})

        logger.info(f"Notification sent: {message}")
        return True

def main():
    runner = TestRunner()

    # Execute the test workflow
    workflow_result = runner.execute_test_workflow()

    # Monitor health
    health_status = runner.monitor_system_health()

    # Backup state
    backup_success = runner.backup_system_state()

    # Send notification
    if workflow_result["status"] == "completed":
        runner.send_notification("Test workflow completed successfully.")
    else:
        runner.send_notification(f"Test workflow failed: {workflow_result.get('message', 'Unknown error')}")

    # Output structured result
    final_output = {
        "workflow": workflow_result,
        "health": health_status,
        "backup_status": "success" if backup_success else "failed"
    }

    print(json.dumps(final_output, indent=2))

if __name__ == "__main__":
    main()
